24	// toastDuration is how long an error stays in the status bar; the log keeps it for good.
25	var toastDuration = 5 * time.Second
26	
27	// maxLogEntries caps the error log, dropping the oldest entries.
28	const maxLogEntries = 500
29	
30	// reportError adds err to the error log and shows it in the status bar until the returned
31	// command expires it. Joined errors (one per failed file) become one log entry each.
32	func (m *model) reportError(err error) tea.Cmd {
33		if err == nil {
34			return nil
35		}
36		lines := strings.Split(err.Error(), "\n")
37		now := time.Now()
38		for _, line := range lines {
39			m.errLog = append(m.errLog, logEntry{time: now, text: line})
40		}
41		if len(m.errLog) > maxLogEntries {
42			m.errLog = m.errLog[len(m.errLog)-maxLogEntries:]
43		}
44		m.toast = lines[0]
45		if len(lines) > 1 {
46			m.toast += fmt.Sprintf(" (+%d more, %s for the log)", len(lines)-1, m.keyMap.ErrorLog.Key)
47		}
48		m.toastID++
49		id := m.toastID
50		return tea.Tick(toastDuration, func(time.Time) tea.Msg { return toastExpiredMsg{id: id} })
51	}
