63	// resolveConflicts runs the pending copy/move once every conflict has been decided:
64	// the files that had no conflict together with the ones chosen for overwriting.
65	func (m *model) resolveConflicts() tea.Cmd {
66		if len(m.overwriteConflicts) > 0 {
67			return nil // Still waiting for a decision
68		}
69		files := append(append([]file{}, m.pendingClean...), m.toOverwrite...)
70		dest, move := m.operationDest, m.isMoving
71		m.cancelTransfer()
72		if len(files) == 0 {
73			return nil
74		}
75		return transferFilesCmd(files, dest, move)
76	}
