78	// cancelTransfer drops the pending copy/move without touching any file.
79	func (m *model) cancelTransfer() {
80		m.isConfirmingOverwrite = false
81		m.overwriteConflicts = nil
82		m.pendingClean = nil
83		m.toOverwrite = nil
84		m.operationDest = ""
